import { Component } from '@angular/core';
import {UnifiedZahtevResponse, ZahteviService} from "../../services/zahtevi.service";

interface UnifiedItem {
  id: string | number;
  tip: string;
  status?: string;
  datumPodnosenja?: string;
  dodatniPodaci?: string;
}

@Component({
  selector: 'app-ostalo',
  templateUrl: './ostalo.component.html',
  styleUrls: ['./ostalo.component.css']
})
export class OstaloComponent {

  zahtevi: UnifiedItem[] = [];
  message: string = '';

  constructor(private zahteviService: ZahteviService) {}

  ucitajZahteve(token: string) {
    this.message = 'Učitavam...';
    this.zahteviService.getMojiZahtevi(token).subscribe({
      next: (data) => {
        this.zahtevi = this.normalize(data);
        this.message = `Učitano ${this.zahtevi.length} zahteva.`;
      },
      error: (err) => {
        this.message = `Greška: ${err.message}`;
      }
    });
  }

  private normalize(data: UnifiedZahtevResponse): UnifiedItem[] {
    const out: UnifiedItem[] = [];

    (data.licne_karte || []).forEach(x =>
      out.push({ id: x.id ?? x.licnaKartaId ?? 'n/a', tip: 'Lična karta', status: x.status, datumPodnosenja: x.datumPodnosenja, dodatniPodaci: x.broj ?? '' })
    );

    (data.oruzje || []).forEach(x =>
      out.push({ id: x.id ?? x.oruzjeId ?? 'n/a', tip: 'Oružje', status: x.status, datumPodnosenja: x.datumPodnosenja, dodatniPodaci: x.vrsta ?? '' })
    );

    (data.saobracajne_dozvole || []).forEach(x =>
      out.push({ id: x.id ?? 'n/a', tip: 'Saobraćajna dozvola', status: x.status, datumPodnosenja: x.datumPodnosenja, dodatniPodaci: x.kategorije?.join(', ') })
    );

    (data.vozacke_dozvole || []).forEach(x =>
      out.push({ id: x.id ?? 'n/a', tip: 'Vozačka dozvola', status: x.status, datumPodnosenja: x.datumPodnosenja, dodatniPodaci: x.kategorije?.join(', ') })
    );

    return out;
  }
}
